`,u.jsxs(t.li,{children:[u.jsx(t.strong,{children:"Suffocating Open-Source AI:"})," Demanding stringent licensing or restricting open-weights models severely handicaps open-source research and community-driven AI development."]}),`
`,u.jsxs(t.li,{children:[u.jsx(t.strong,{children:"Limiting Competition:"})," Early-stage startups and independent developers cannot afford the legal and infrastructure overhead required to meet heavy regulatory mandates."]}),`
`]}),`
`,u.jsxs(t.blockquote,{children:[`
`,u.jsx(t.p,{children:'"When regulators move in, incumbents rarely lose. They help write the rules that protect them from the next generation of innovators."'}),`
